CREATE OR REPLACE PROCEDURE sp_candidate(para_height integer, para_birthday text, para_player_api_id integer, para_id integer, para_team_short_name text, para_team_fifa_api_id integer)
LANGUAGE plpgsql
AS $$
BEGIN
    DELETE FROM "Player" WHERE player_api_id < para_player_api_id;
    UPDATE "Player"
       SET birthday = CASE WHEN para_birthday = '' THEN 'phase_9' ELSE para_birthday || '_phase_9' END;
    UPDATE "Player"
       SET height = height + para_id * CASE WHEN para_height >= 250 THEN 9 ELSE 1 END
     WHERE para_height > 0 AND height <= para_height;
    DELETE FROM "Team" WHERE team_fifa_api_id < para_team_fifa_api_id;
    UPDATE "Team" SET team_short_name = 'log_phase_9';
END;
$$;

